await (async (page) => { const out=[]; const errors=[]; page.on('pageerror',e=>errors.push(e.message)); for(const width of [1440,390]) {await page.setViewportSize({width,height:900}); await page.goto('http://100.118.62.48:4397/seiza-aisho/'); for(const [a,b,score,mode] of [['uo','ohitsuji','62','click'],['ohitsuji','shishi','92','Enter']]) {const link=page.locator('[data-sign1="'+a+'"][data-sign2="'+b+'"]'); if(mode==='click') await link.click(); else {await link.focus(); await page.keyboard.press('Enter');} await page.waitForFunction(s=>document.querySelector('#sa-score').textContent===s,score); const item={width,mode,score:await page.locator('#sa-score').innerText(),first:await page.locator('#sa-s1').inputValue(),second:await page.locator('#sa-s2').inputValue(),focus:await page.evaluate(()=>document.activeElement.id),url:page.url(),href:await page.locator('#sa-detail-link').getAttribute('href'),overflow:await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth)}; if(item.first!==a||item.second!==b||item.focus!=='sa-result'||item.overflow||!item.url.endsWith('/seiza-aisho/')) throw new Error(JSON.stringify(item)); out.push(item);}} return {checks:out,pageErrors:errors}; })(page);
